    step: Transition, initial: Configuration, steps: int
) -> List[Configuration]:
    """Return the finite trace, stopping when the transition returns None."""
    trace = [initial]
    current = initial
    for _ in range(steps):
        nxt = step(*current)
        if nxt is None:
            break
